makeSample=function(){
const n=draft.name,a=draft.storyLanguage==='ar',w=draft.world;
const stories={
forest:{ar:[`كان ${n} يحب زيارة بستان جدّه في قرية بين جبال عُمان. لبس كُمّته وقال: «تو جاهز للمغامرة!»`,`قال الجد: «يا ولدي، الماء نعمة. تعال نشوف الفلج ونتعلّم كيف نحافظ عليه».`,`لاحظ ${n} أن الماء في الساقية صار قليلًا، وأن شتلة صغيرة بدأت تذبل.`,`ظهر ثعلب صغير من خلف شجرة رمان. في عالم الحكاية، قال: «هيّا ندور السبب معًا».`,`أراد ${n} الاقتراب وحده، ثم تذكّر أن يسأل الكبير أولًا. نادى جدّه وانتظره.`,`مشيا بجانب الساقية بحذر، فشاهدا أوراقًا وأغصانًا تعترض مجرى الماء.`,`قال ${n}: «أنا بساعدك من المكان الآمن». جمع الأوراق اليابسة بعيدًا عن حافة الماء.`,`أزال الجد الأغصان بأداة مناسبة، فعادت الساقية تغنّي بين البساتين.`,`تعلم ${n} أن تعاون الصغار والكبار يجعل العمل أسهل وأكثر أمانًا.`,`سقيا الشتلة بالقدر الذي تحتاجه، دون إسراف. قال الجد: «زين، كل قطرة لها قيمة».`,`نظر ${n} إلى البستان وقال: «البطل ما يحتاج قوة خارقة؛ يكفي يهتم ويسأل ويساعد».`,`عاد إلى البيت وفي قلبه وعد: أحافظ على الماء، وأستأذن قبل المغامرة، وأتعاون مع من حولي.`],en:[`${n} loved visiting a grandparent’s garden in an Omani mountain village. Their embroidered kumma was ready for an adventure.`,`“Water is precious,” said the grandparent. “Let’s learn how to care for our falaj waterway.”`,`${n} noticed that the little irrigation channel carried less water, and a seedling was wilting.`,`A friendly fox appeared beneath a pomegranate tree. In this storybook world, it could speak! “Let’s find out why.”`,`${n} wanted to investigate, then remembered to ask a trusted adult first.`,`They followed the channel carefully and saw leaves and branches blocking the flow.`,`“I can help from a safe spot,” said ${n}, gathering dry leaves away from the water’s edge.`,`The grandparent used a suitable tool to remove the branches. Water flowed gently again.`,`${n} learned that children and adults can work together safely.`,`They gave the seedling just the water it needed. Every drop had a purpose.`,`“Heroes care, ask questions, and help,” said ${n}, smiling at the garden.`,`Back home, ${n} made a promise: save water, ask before exploring, and work together.`]},
space:{ar:[`في مساء هادئ في عُمان، نظر ${n} إلى السماء وسأل: «ليش النجوم تلمع؟»`,`قالت أمّه: «سؤال زين! كل معرفة تبدأ بفضول». وفتحا كتابًا عن السماء.`,`وفي حلم جميل، وجد ${n} مركبة فضائية صغيرة وصديقًا آليًا اسمه نور.`,`قال نور: «قبل الانطلاق، نلبس حزام الأمان ونراجع خطتنا».`,`شاهد ${n} الأرض زرقاء وجميلة، وتذكّر أن عُمان وبيته وأصدقاءه يعيشون عليها.`,`سأل: «هل القمر يضيء من نفسه؟» قال نور: «نراه مضيئًا لأنه يعكس ضوء الشمس».`,`كتب ${n} المعلومة في دفتره، ورسم الشمس والقمر ليشرحها لأصدقائه.`,`ثم سأله نور سؤالًا لم يعرف إجابته. قال ${n}: «ما أعرف بعد، بس أقدر أتعلّم».`,`ابتسم نور: «أحسنت! الاعتراف بأننا لا نعرف يساعدنا على البحث».`,`وعندما حان وقت العودة، راجعا الطريق معًا بدل التسرع.`,`استيقظ ${n} وفي قلبه حماس. شارك أمّه حلمه وسألها عن زيارة مكان لتعلّم العلوم.`,`عرف بطلنا أن الفضول جميل، وأن السؤال والتجربة الآمنة والتعلّم مع الكبار تصنع اكتشافات كبيرة.`],en:[`One quiet evening in Oman, ${n} looked up and asked, “Why do stars twinkle?”`,`“What a lovely question,” said Mum. “Learning begins with curiosity.” They opened a book about the sky.`,`In a wonderful dream, ${n} found a little spacecraft and a friendly robot called Noor.`,`“Before we leave, let’s check our plan and fasten our safety belts,” Noor said.`,`${n} saw the blue Earth and remembered that Oman, home, and all their friends were there.`,`“Does the Moon make its own light?” asked ${n}. “We see it because it reflects sunlight,” Noor explained.`,`${n} drew the Sun and Moon in a notebook to share the idea with friends.`,`Noor asked another question. “I don’t know yet, but I can learn,” said ${n}.`,`“Exactly! Knowing what we don’t know helps us ask better questions.”`,`When it was time to return, they checked the route together instead of rushing.`,`${n} woke up excited, shared the dream with Mum, and asked where they could learn more about science.`,`Our little hero learned that curiosity, questions, safe exploration, and trusted adults help discoveries grow.`]},
ocean:{ar:[`خرج ${n} مع أسرته في نزهة على شاطئ في عُمان. قال: «البحر اليوم واجد جميل!»`,`وقبل اللعب، اتفقوا أن يبقوا معًا وبعيدًا عن الماء دون مرافقة الكبار.`,`رأى ${n} سلحفاة صغيرة في حكاية خيالية، وكانت تنظر إلى كيس قرب الرمل.`,`قالت السلحفاة: «البحر بيتنا، ونحبّه نظيفًا». شعر ${n} أن عنده مهمة جميلة.`,`تذكّر أن الكائنات البحرية لا نلمسها ولا نطاردها. راقبها بهدوء من بعيد.`,`نادى أحد الكبار وقال: «فيه مخلفات هنا، كيف نقدر ننظف المكان بأمان؟»`,`أحضر الكبير قفازات وكيسًا مناسبًا، وحدّد الأشياء الآمنة التي يمكن جمعها.`,`وجد ${n} قطعة حادة، فلم يلمسها. أشار إليها للكبير وابتعد.`,`تعاونت الأسرة على جمع المخلفات، دون إزعاج الكائنات أو إزالة الأصداف الحية.`,`ومن بعيد، رأى ${n} قاربًا خشبيًا. سأل عن قصص البحر والبحّارة في عُمان.`,`قال لأسرته: «زين لو نخلي المكان أنظف مما لقيناه». ابتسم الجميع.`,`عاد بطلنا بذكرى جميلة: أحمي البحر، وأرفق بالكائنات، وأطلب مساعدة الكبار حين أحتاج.`],en:[`${n} visited an Omani beach with the family. “The sea looks beautiful today!”`,`Before playing, they agreed to stay together and keep away from the water without adult supervision.`,`In this imaginary story, a little turtle noticed a plastic bag near the sand.`,`“The sea is our home. We love to keep it clean,” said the turtle. ${n} had an idea.`,`${n} remembered to watch sea creatures quietly, without touching or chasing them.`,`“There is litter here. How can we help safely?” ${n} asked a trusted adult.`,`The adult brought gloves and a suitable bag and explained which items were safe to collect.`,`${n} spotted something sharp, left it untouched, and pointed it out to the adult.`,`The family worked together without disturbing wildlife or taking living shells.`,`A wooden boat sailed in the distance. ${n} asked about Oman’s seafaring stories.`,`“Let’s leave this place cleaner than we found it,” said ${n}. Everyone smiled.`,`Our hero went home with a promise: care for the sea, be gentle with wildlife, and ask adults for help.`]}
};
const pages=[...stories[w][a?'ar':'en']];if(draft.dedication)pages[0]=draft.dedication+'\n\n'+pages[0];
const title=a?(w==='forest'?`${n} وسرّ الفلج`:`${n} و${titleFor(w,'ar')}`):`${n} & ${titleFor(w,'en')}`;
return{id:crypto.randomUUID(),name:n,world:w,language:draft.storyLanguage,title,pages,createdAt:new Date().toISOString(),sample:true,identity:'Omani'};
};
example=function(){const previous=draft;draft={name:lang==='ar'?'عيسى':'Isa',world:'forest',storyLanguage:lang,dedication:''};const s=makeSample();draft=previous;return s};
